import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        String digits = s.substring(1, s.length() - 1);

        for (int split = 1; split < digits.length(); split++) {
            List<String> leftNumbers = generateNumbers(digits.substring(0, split));
            List<String> rightNumbers = generateNumbers(digits.substring(split));

            for (String left : leftNumbers) {
                for (String right : rightNumbers) {
                    result.add("(" + left + ", " + right + ")");
                }
            }
        }

        return result;
    }

    private List<String> generateNumbers(String digits) {
        List<String> numbers = new ArrayList<>();
        int length = digits.length();

        if (length == 1 || digits.charAt(0) != '0') {
            numbers.add(digits);
        }

        if (digits.charAt(length - 1) == '0') {
            return numbers;
        }

        for (int decimal = 1; decimal < length; decimal++) {
            String integerPart = digits.substring(0, decimal);

            if (integerPart.length() > 1 && integerPart.charAt(0) == '0') {
                continue;
            }

            numbers.add(integerPart + "." + digits.substring(decimal));
        }

        return numbers;
    }
}
