import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

class Solution {
    public int numFactoredBinaryTrees(int[] arr) {
        final long MOD = 1_000_000_007L;

        Arrays.sort(arr);
        Map<Integer, Long> ways = new HashMap<>();
        long answer = 0;

        for (int i = 0; i < arr.length; i++) {
            long count = 1;

            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] != 0) {
                    continue;
                }

                int otherFactor = arr[i] / arr[j];
                Long otherWays = ways.get(otherFactor);

                if (otherWays != null) {
                    count = (count + ways.get(arr[j]) * otherWays) % MOD;
                }
            }

            ways.put(arr[i], count);
            answer = (answer + count) % MOD;
        }

        return (int) answer;
    }
}
