class Solution {
    public int countVowelPermutation(int n) {
        final long MOD = 1_000_000_007L;

        long a = 1;
        long e = 1;
        long i = 1;
        long o = 1;
        long u = 1;

        for (int length = 2; length <= n; length++) {
            long nextA = (e + i + u) % MOD;
            long nextE = (a + i) % MOD;
            long nextI = (e + o) % MOD;
            long nextO = i;
            long nextU = (i + o) % MOD;

            a = nextA;
            e = nextE;
            i = nextI;
            o = nextO;
            u = nextU;
        }

        return (int) ((a + e + i + o + u) % MOD);
    }
}
