class MKAverage {
    private static final int MAX_VALUE = 100000;

    private final int m;
    private final int k;
    private final int[] countTree;
    private final long[] sumTree;
    private final java.util.ArrayDeque<Integer> window;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        this.countTree = new int[MAX_VALUE + 1];
        this.sumTree = new long[MAX_VALUE + 1];
        this.window = new java.util.ArrayDeque<>();
    }

    public void addElement(int num) {
        window.offerLast(num);
        update(num, 1);

        if (window.size() > m) {
            int removed = window.pollFirst();
            update(removed, -1);
        }
    }

    public int calculateMKAverage() {
        if (window.size() < m) {
            return -1;
        }

        long middleSum = sumSmallest(m - k) - sumSmallest(k);
        return (int) (middleSum / (m - 2 * k));
    }

    private void update(int value, int delta) {
        for (int i = value; i <= MAX_VALUE; i += i & -i) {
            countTree[i] += delta;
            sumTree[i] += (long) value * delta;
        }
    }

    private long sumSmallest(int targetCount) {
        if (targetCount == 0) {
            return 0L;
        }

        int index = 0;
        int count = 0;
        long sum = 0L;

        for (int bit = Integer.highestOneBit(MAX_VALUE); bit != 0; bit >>= 1) {
            int next = index + bit;
            if (next <= MAX_VALUE && count + countTree[next] < targetCount) {
                index = next;
                count += countTree[next];
                sum += sumTree[next];
            }
        }

        int boundaryValue = index + 1;
        return sum + (long) (targetCount - count) * boundaryValue;
    }
}

