            if (vowelIndex == -1) {
                lastConsonant = i;
            } else {
                lastSeen[vowelIndex] = i;

                int earliestVowel = lastSeen[0];
                for (int position : lastSeen) {
                    earliestVowel = Math.min(earliestVowel, position);
