class Solution {
    public int largestMagicSquare(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        int[][] rowPrefix = new int[m][n + 1];
        int[][] colPrefix = new int[m + 1][n];
        int[][] mainDiagonal = new int[m + 1][n + 1];
        int[][] antiDiagonal = new int[m + 1][n + 1];

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                rowPrefix[r][c + 1] = rowPrefix[r][c] + grid[r][c];
                colPrefix[r + 1][c] = colPrefix[r][c] + grid[r][c];
                mainDiagonal[r + 1][c + 1] =
                        mainDiagonal[r][c] + grid[r][c];
            }
        }

        for (int r = 0; r < m; r++) {
            for (int c = n - 1; c >= 0; c--) {
                antiDiagonal[r + 1][c] =
                        antiDiagonal[r][c + 1] + grid[r][c];
            }
        }

        for (int size = Math.min(m, n); size >= 1; size--) {
            for (int top = 0; top + size <= m; top++) {
                for (int left = 0; left + size <= n; left++) {
                    int bottom = top + size;
                    int right = left + size;

                    int target = mainDiagonal[bottom][right]
                            - mainDiagonal[top][left];

                    int otherDiagonal = antiDiagonal[bottom][left]
                            - antiDiagonal[top][right];

                    if (otherDiagonal != target) {
                        continue;
                    }

                    boolean magic = true;

                    for (int r = top; r < bottom; r++) {
                        int rowSum = rowPrefix[r][right]
                                - rowPrefix[r][left];
                        if (rowSum != target) {
                            magic = false;
                            break;
                        }
                    }

                    if (!magic) {
                        continue;
                    }

                    for (int c = left; c < right; c++) {
                        int colSum = colPrefix[bottom][c]
                                - colPrefix[top][c];
                        if (colSum != target) {
                            magic = false;
                            break;
                        }
                    }

                    if (magic) {
                        return size;
                    }
                }
            }
        }

        return 1;
    }
}
