class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;

        for (int i = 0; i < n; i++) {
            flowers[i] = Math.min(flowers[i], target);
        }
        java.util.Arrays.sort(flowers);

        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        int incomplete = lowerBound(flowers, n, target);
        long answer = 0;
        long completionCost = 0;

        for (int remaining = incomplete; remaining >= 0; remaining--) {
            if (completionCost > newFlowers) {
                break;
            }

            int complete = n - remaining;
            long beauty = (long) complete * full;

            if (remaining > 0) {
                long budget = newFlowers - completionCost;
                int minimum = maximumMinimum(flowers, prefix, remaining, budget, target);
                beauty += (long) minimum * partial;
            }

            answer = Math.max(answer, beauty);

            if (remaining > 0) {
                completionCost += (long) target - flowers[remaining - 1];
            }
        }

        return answer;
    }

    private int maximumMinimum(int[] flowers, long[] prefix, int size,
                               long budget, int target) {
        int low = 0;
        int high = target - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            int count = lowerBound(flowers, size, mid);
            long cost = (long) mid * count - prefix[count];

            if (cost <= budget) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return high;
    }

    private int lowerBound(int[] values, int size, int target) {
        int low = 0;
        int high = size;

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (values[mid] < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        return low;
    }
}
