class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        boolean[] infected = new boolean[n];

        for (int node : initial) {
            infected[node] = true;
        }

        boolean[] visited = new boolean[n];
        int[] saved = new int[n];
        int[] queue = new int[n];

        for (int start = 0; start < n; start++) {
            if (infected[start] || visited[start]) {
                continue;
            }

            boolean[] connectedSources = new boolean[n];
            int head = 0;
            int tail = 0;
            int componentSize = 0;

            queue[tail++] = start;
            visited[start] = true;

            while (head < tail) {
                int node = queue[head++];
                componentSize++;

                for (int next = 0; next < n; next++) {
                    if (graph[node][next] == 0) {
                        continue;
                    }

                    if (infected[next]) {
                        connectedSources[next] = true;
                    } else if (!visited[next]) {
                        visited[next] = true;
                        queue[tail++] = next;
                    }
                }
            }

            int uniqueSource = -1;
            int sourceCount = 0;

            for (int source : initial) {
                if (connectedSources[source]) {
                    uniqueSource = source;
                    sourceCount++;
                }
            }

            if (sourceCount == 1) {
                saved[uniqueSource] += componentSize;
            }
        }

        int answer = Integer.MAX_VALUE;
        int bestSaved = -1;

        for (int source : initial) {
            if (saved[source] > bestSaved ||
                (saved[source] == bestSaved && source < answer)) {
                bestSaved = saved[source];
                answer = source;
            }
        }

        return answer;
    }
}
