class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        int inf = Integer.MAX_VALUE / 2;
        int[][] dp = new int[maxTime + 1][n];

        for (int time = 0; time <= maxTime; time++) {
            java.util.Arrays.fill(dp[time], inf);
        }

        dp[0][0] = passingFees[0];

        for (int time = 1; time <= maxTime; time++) {
            for (int[] edge : edges) {
                int u = edge[0];
                int v = edge[1];
                int travelTime = edge[2];

                if (travelTime > time) {
                    continue;
                }

                if (dp[time - travelTime][u] != inf) {
                    dp[time][v] = Math.min(
                        dp[time][v],
                        dp[time - travelTime][u] + passingFees[v]
                    );
                }

                if (dp[time - travelTime][v] != inf) {
                    dp[time][u] = Math.min(
                        dp[time][u],
                        dp[time - travelTime][v] + passingFees[u]
                    );
                }
            }
        }

        int answer = inf;
        for (int time = 0; time <= maxTime; time++) {
            answer = Math.min(answer, dp[time][n - 1]);
        }

        return answer == inf ? -1 : answer;
    }
}
