class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.length;
        int n = students[0].length;

        int[][] score = new int[m][m];
        for (int student = 0; student < m; student++) {
            for (int mentor = 0; mentor < m; mentor++) {
                for (int question = 0; question < n; question++) {
                    if (students[student][question] == mentors[mentor][question]) {
                        score[student][mentor]++;
                    }
                }
            }
        }

        int[] dp = new int[1 << m];

        for (int mask = 0; mask < (1 << m); mask++) {
            int student = Integer.bitCount(mask);
            if (student == m) {
                continue;
            }

            for (int mentor = 0; mentor < m; mentor++) {
                if ((mask & (1 << mentor)) == 0) {
                    int nextMask = mask | (1 << mentor);
                    dp[nextMask] = Math.max(
                        dp[nextMask],
                        dp[mask] + score[student][mentor]
                    );
                }
            }
        }

        return dp[(1 << m) - 1];
    }
}
