import java.util.*;

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        int leftRem = 0;
        int rightRem = 0;

        for (char c : s.toCharArray()) {
            if (c == '(') {
                leftRem++;
            } else if (c == ')') {
                if (leftRem > 0) {
                    leftRem--;
                } else {
                    rightRem++;
                }
            }
        }

        Set<String> result = new HashSet<>();
        backtrack(s, 0, 0, leftRem, rightRem, new StringBuilder(), result);
        return new ArrayList<>(result);
    }

    private void backtrack(String s, int index, int balance,
                           int leftRem, int rightRem,
                           StringBuilder current, Set<String> result) {
        if (index == s.length()) {
            if (balance == 0 && leftRem == 0 && rightRem == 0) {
                result.add(current.toString());
            }
            return;
        }

        if (s.length() - index < leftRem + rightRem) {
            return;
        }

        char c = s.charAt(index);
        int length = current.length();

        if (c == '(') {
            if (leftRem > 0) {
                backtrack(s, index + 1, balance, leftRem - 1, rightRem,
                          current, result);
            }

            current.append(c);
            backtrack(s, index + 1, balance + 1, leftRem, rightRem,
                      current, result);
            current.setLength(length);
        } else if (c == ')') {
            if (rightRem > 0) {
                backtrack(s, index + 1, balance, leftRem, rightRem - 1,
                          current, result);
            }

            if (balance > 0) {
                current.append(c);
                backtrack(s, index + 1, balance - 1, leftRem, rightRem,
                          current, result);
                current.setLength(length);
            }
        } else {
            current.append(c);
            backtrack(s, index + 1, balance, leftRem, rightRem,
                      current, result);
            current.setLength(length);
        }
    }
}
