import java.util.TreeMap;

class Solution {
    private final TreeMap<Integer, Integer> lower = new TreeMap<>();
    private final TreeMap<Integer, Integer> upper = new TreeMap<>();
    private int lowerSize;
    private int upperSize;

    public double[] medianSlidingWindow(int[] nums, int k) {
        lower.clear();
        upper.clear();
        lowerSize = 0;
        upperSize = 0;

        double[] medians = new double[nums.length - k + 1];

        for (int i = 0; i < k; i++) {
            add(nums[i]);
        }

        for (int left = 0; left + k <= nums.length; left++) {
            medians[left] = getMedian(k);

            if (left + k < nums.length) {
                remove(nums[left]);
                add(nums[left + k]);
            }
        }

        return medians;
    }

    private void add(int value) {
        if (lower.isEmpty() || value <= lower.lastKey()) {
            addToMap(lower, value);
            lowerSize++;
        } else {
            addToMap(upper, value);
            upperSize++;
        }
        rebalance();
    }

    private void remove(int value) {
        if (lower.containsKey(value)) {
            removeFromMap(lower, value);
            lowerSize--;
        } else {
            removeFromMap(upper, value);
            upperSize--;
        }
        rebalance();
    }

    private void rebalance() {
        int totalSize = lowerSize + upperSize;
        int targetLowerSize = (totalSize + 1) / 2;

        while (lowerSize > targetLowerSize) {
            int value = lower.lastKey();
            removeFromMap(lower, value);
            lowerSize--;
            addToMap(upper, value);
            upperSize++;
        }

        while (lowerSize < targetLowerSize) {
            int value = upper.firstKey();
            removeFromMap(upper, value);
            upperSize--;
            addToMap(lower, value);
            lowerSize++;
        }
    }

    private double getMedian(int k) {
        if ((k & 1) == 1) {
            return lower.lastKey();
        }
        return ((double) lower.lastKey() + (double) upper.firstKey()) / 2.0;
    }

    private void addToMap(TreeMap<Integer, Integer> map, int value) {
        map.put(value, map.getOrDefault(value, 0) + 1);
    }

    private void removeFromMap(TreeMap<Integer, Integer> map, int value) {
        int count = map.get(value);
        if (count == 1) {
            map.remove(value);
        } else {
            map.put(value, count - 1);
        }
    }
}
