import java.util.*;

class Solution {
    private List<int[]> stickerCounts;
    private Map<String, Integer> memo;
    private static final int INF = 1_000_000;

    public int minStickers(String[] stickers, String target) {
        int[] targetCount = new int[26];
        for (char c : target.toCharArray()) {
            targetCount[c - 'a']++;
        }

        stickerCounts = new ArrayList<>();

        for (String sticker : stickers) {
            int[] count = new int[26];
            for (char c : sticker.toCharArray()) {
                int index = c - 'a';
                if (targetCount[index] > 0) {
                    count[index] = Math.min(count[index] + 1, targetCount[index]);
                }
            }

            boolean useful = false;
            for (int value : count) {
                if (value > 0) {
                    useful = true;
                    break;
                }
            }
            if (!useful) {
                continue;
            }

            boolean dominated = false;
            for (int[] existing : stickerCounts) {
                if (dominates(existing, count)) {
                    dominated = true;
                    break;
                }
            }
            if (dominated) {
                continue;
            }

            stickerCounts.removeIf(existing -> dominates(count, existing));
            stickerCounts.add(count);
        }

        boolean[] available = new boolean[26];
        for (int[] sticker : stickerCounts) {
            for (int i = 0; i < 26; i++) {
                if (sticker[i] > 0) {
                    available[i] = true;
                }
            }
        }

        for (int i = 0; i < 26; i++) {
            if (targetCount[i] > 0 && !available[i]) {
                return -1;
            }
        }

        char[] chars = target.toCharArray();
        Arrays.sort(chars);

        memo = new HashMap<>();
        memo.put("", 0);

        int answer = dfs(new String(chars));
        return answer >= INF ? -1 : answer;
    }

    private int dfs(String remaining) {
        Integer cached = memo.get(remaining);
        if (cached != null) {
            return cached;
        }

        int[] needed = new int[26];
        for (int i = 0; i < remaining.length(); i++) {
            needed[remaining.charAt(i) - 'a']++;
        }

        int firstLetter = remaining.charAt(0) - 'a';
        int result = INF;

        for (int[] sticker : stickerCounts) {
            if (sticker[firstLetter] == 0) {
                continue;
            }

            StringBuilder next = new StringBuilder();
            for (int i = 0; i < 26; i++) {
                int left = Math.max(0, needed[i] - sticker[i]);
                for (int j = 0; j < left; j++) {
                    next.append((char) ('a' + i));
                }
            }

            int subResult = dfs(next.toString());
            if (subResult < INF) {
                result = Math.min(result, 1 + subResult);
            }
        }

        memo.put(remaining, result);
        return result;
    }

    private boolean dominates(int[] first, int[] second) {
        for (int i = 0; i < 26; i++) {
            if (first[i] < second[i]) {
                return false;
            }
        }
        return true;
    }
}
