class Solution {
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        UnionFind uf = new UnionFind(4 * n * n);

        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                int base = 4 * (row * n + col);
                char ch = grid[row].charAt(col);

                if (ch == ' ') {
                    uf.union(base, base + 1);
                    uf.union(base + 1, base + 2);
                    uf.union(base + 2, base + 3);
                } else if (ch == '/') {
                    uf.union(base, base + 3);
                    uf.union(base + 1, base + 2);
                } else {
                    uf.union(base, base + 1);
                    uf.union(base + 2, base + 3);
                }

                if (row + 1 < n) {
                    int below = 4 * ((row + 1) * n + col);
                    uf.union(base + 2, below);
                }

                if (col + 1 < n) {
                    int right = 4 * (row * n + col + 1);
                    uf.union(base + 1, right + 3);
                }
            }
        }

        return uf.components;
    }

    private static class UnionFind {
        private final int[] parent;
        private final int[] rank;
        private int components;

        UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            components = size;

            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        int find(int node) {
            if (parent[node] != node) {
                parent[node] = find(parent[node]);
            }
            return parent[node];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);

            if (rootA == rootB) {
                return;
            }

            if (rank[rootA] < rank[rootB]) {
                parent[rootA] = rootB;
            } else if (rank[rootA] > rank[rootB]) {
                parent[rootB] = rootA;
            } else {
                parent[rootB] = rootA;
                rank[rootA]++;
            }

            components--;
        }
    }
}
