class Solution {
    private final int[][][] earliest = new int[29][29][29];
    private final int[][][] latest = new int[29][29][29];

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        return solve(n, firstPlayer, secondPlayer);
    }

    private int[] solve(int n, int a, int b) {
        if (a + b == n + 1) {
            return new int[]{1, 1};
        }

        if (earliest[n][a][b] != 0) {
            return new int[]{earliest[n][a][b], latest[n][a][b]};
        }

        int[] result = {Integer.MAX_VALUE, Integer.MIN_VALUE};
        enumerate(n, a, b, 1, 0, 0, result);

        earliest[n][a][b] = result[0];
        latest[n][a][b] = result[1];
        return result;
    }

    private void enumerate(int n, int a, int b, int match,
                           int beforeA, int beforeB, int[] result) {
        int pairs = n / 2;

        if (match > pairs) {
            if ((n & 1) == 1) {
                int middle = pairs + 1;
                if (middle < a) beforeA++;
                if (middle < b) beforeB++;
            }

            int nextA = beforeA + 1;
            int nextB = beforeB + 1;
            int[] next = solve((n + 1) / 2, nextA, nextB);

            result[0] = Math.min(result[0], next[0] + 1);
            result[1] = Math.max(result[1], next[1] + 1);
            return;
        }

        int left = match;
        int right = n + 1 - match;

        if (left == a || right == a) {
            advance(n, a, b, match, beforeA, beforeB, result, a);
        } else if (left == b || right == b) {
            advance(n, a, b, match, beforeA, beforeB, result, b);
        } else {
            advance(n, a, b, match, beforeA, beforeB, result, left);
            advance(n, a, b, match, beforeA, beforeB, result, right);
        }
    }

    private void advance(int n, int a, int b, int match,
                         int beforeA, int beforeB, int[] result, int winner) {
        enumerate(
            n, a, b, match + 1,
            beforeA + (winner < a ? 1 : 0),
            beforeB + (winner < b ? 1 : 0),
            result
        );
    }
}
