class Solution {
    public int[] kWeakestRows(int[][] mat, int k) {
        int m = mat.length;
        int[] rows = new int[m];

        for (int i = 0; i < m; i++) {
            int left = 0;
            int right = mat[i].length;

            while (left < right) {
                int mid = left + (right - left) / 2;
                if (mat[i][mid] == 1) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }

            rows[i] = left * m + i;
        }

        java.util.Arrays.sort(rows);

        int[] result = new int[k];
        for (int i = 0; i < k; i++) {
            result[i] = rows[i] % m;
        }

        return result;
    }
}
