    private String[] words;
    private String result;
    private int[] mapping;
    private boolean[] used;
    private boolean[] leading;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        this.mapping = new int[26];
        this.used = new boolean[10];
        this.leading = new boolean[26];

        java.util.Arrays.fill(mapping, -1);

        boolean[] present = new boolean[26];
        int unique = 0;
        int maxWordLength = 0;

        for (String word : words) {
            maxWordLength = Math.max(maxWordLength, word.length());
            if (word.length() > 1) {
                leading[word.charAt(0) - 'A'] = true;
            }
            for (int i = 0; i < word.length(); i++) {
                int letter = word.charAt(i) - 'A';
                if (!present[letter]) {
                    present[letter] = true;
                    unique++;
                }
            }
        }

        if (result.length() > 1) {
            leading[result.charAt(0) - 'A'] = true;
        }
        for (int i = 0; i < result.length(); i++) {
            int letter = result.charAt(i) - 'A';
            if (!present[letter]) {
                present[letter] = true;
                unique++;
            }
        }

        if (unique > 10
                || result.length() < maxWordLength
                || result.length() > maxWordLength + 1) {
            return false;
        }

        return solveColumn(0, 0, 0);
    }

    private boolean solveColumn(int column, int wordIndex, int sum) {
        if (column == result.length()) {
            return sum == 0;
        }

        if (wordIndex < words.length) {
            String word = words[wordIndex];
            int position = word.length() - 1 - column;

            if (position < 0) {
                return solveColumn(column, wordIndex + 1, sum);
            }

            int letter = word.charAt(position) - 'A';

            if (mapping[letter] != -1) {
                return solveColumn(column, wordIndex + 1,
                        sum + mapping[letter]);
