        mapping[resultLetter] = requiredDigit;
        used[requiredDigit] = true;

        if (solveColumn(column + 1, 0, carry)) {
            return true;
        }

        mapping[resultLetter] = -1;
        used[requiredDigit] = false;
        return false;
