class Solution {
    public boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indegree = new int[n];

        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1 && ++indegree[leftChild[i]] > 1) {
                return false;
            }
            if (rightChild[i] != -1 && ++indegree[rightChild[i]] > 1) {
                return false;
            }
        }

        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                if (root != -1) {
                    return false;
                }
                root = i;
            }
        }

        if (root == -1) {
            return false;
        }

        boolean[] visited = new boolean[n];
        int[] queue = new int[n];
        int front = 0;
        int back = 0;
        int count = 0;

        queue[back++] = root;

        while (front < back) {
            int node = queue[front++];

            if (visited[node]) {
                return false;
            }

            visited[node] = true;
            count++;

            if (leftChild[node] != -1) {
                queue[back++] = leftChild[node];
            }
            if (rightChild[node] != -1) {
                queue[back++] = rightChild[node];
            }
        }

        return count == n;
    }
}
